const fs = await import('node:fs/promises');
const path = await import('node:path');
const { execFileSync } = await import('node:child_process');
const { createHash } = await import('node:crypto');
const i = input.run;
const git = (cwd, ...args) => execFileSync('git', args, { cwd, encoding: 'utf8' }).trim();
const repoPath = await fs.realpath(path.resolve(i.repoPath));
const top = await fs.realpath(git(repoPath, 'rev-parse', '--show-toplevel'));
if (top !== repoPath) throw new Error('repoPath must be the root of a Git checkout. Its root is ' + top);
const baseCommit = git(repoPath, 'rev-parse', '--verify', (i.baseRef || 'HEAD') + '^{commit}');
const words = ((i.issue ? String(i.issue).split('/').pop() + ' ' : '') + i.request).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+/, '').slice(0, 40).replace(/-+$/, '') || 'change';
const taskDir = i.taskDir || path.join('.tasks', words + '-' + createHash('sha256').update(i.request).digest('hex').slice(0, 6));
if (path.isAbsolute(taskDir)) throw new Error('taskDir must be relative to repoPath');
await fs.mkdir(path.resolve(repoPath, taskDir), { recursive: true });
const taskPath = await fs.realpath(path.resolve(repoPath, taskDir));
const rel = path.relative(repoPath, taskPath);
if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) throw new Error('taskDir must stay inside the repository');
return { repoPath, request: i.request, taskDir: rel, size: i.size ?? 'small', issue: i.issue ?? null, baseCommit,
  reviewPolicy: i.reviewPolicy ?? 'auto', createPr: i.createPr ?? false, commitArtifacts: i.commitArtifacts ?? false };

const plan = input.plan;
const root = input.root;
const open = [...(input.planCount === 1 ? input.spec?.decisions ?? [] : []), ...(plan.decisions ?? [])];
const route = open.length ? 'ask' : root.size === 'standard' ? 'review' : root.reviewPolicy === 'always' ? 'ask' : 'build';
const list = open.map((d, n) => (n + 1) + '. ' + d.question + '\n   Why it matters: ' + d.whyItMatters + '\n   Recommended: ' + d.recommendation).join('\n\n');
return { route, decisions: open, summary: plan.summary,
  question: open.length ? ('The plan has decisions only you can settle. Approving accepts each recommendation.\n\n' + list).slice(0, 4000) : 'Approve this plan before any code is written?',
  context: plan.summary };

const r = input.review;
const root = input.root;
const feedback = r.findings.map((f) => '[' + f.id + ' ' + f.severity + '] ' + f.location + ': ' + f.details + ' Recommendation: ' + f.recommendation).join('\n');
let route;
if (r.verdict === 'ready') route = root.reviewPolicy === 'always' ? 'ask' : 'build';
else if (r.verdict === 'revise' && input.count < 2) route = 'revise';
else route = 'ask';
const why = r.verdict === 'ready' ? 'Independent review found the plan ready.'
  : r.verdict === 'blocked' ? 'Independent review could not be completed: ' + r.limitations.join(' ')
  : 'The plan still has review findings after ' + input.count + ' reviews.';
return { route, feedback, review: r, decisions: [], summary: r.summary,
  question: (why + ' Approve the plan as it stands, request changes, or stop?').slice(0, 4000),
  context: (r.summary + (feedback ? '\n\nFindings:\n' + feedback : '')).slice(0, 32000) };

const fs = await import('node:fs/promises');
const path = await import('node:path');
const { createHash } = await import('node:crypto');
const root = input.root;
const repo = await fs.realpath(root.repoPath);
const file = await fs.realpath(path.resolve(repo, input.plan.artifactPath));
const rel = path.relative(repo, file);
if (rel.startsWith('..') || path.isAbsolute(rel)) throw new Error('The plan must be a file inside the repository');
const text = await fs.readFile(file, 'utf8');
return { question: input.ask.question, context: input.ask.context, feedback: input.ask.feedback ?? '',
  file, revision: createHash('sha256').update(text).digest('hex'),
  evidence: text.length > 32000 ? text.slice(0, 31900) + '\n\n[Plan truncated here; open ' + rel + ' for the rest.]' : text };

const fs = await import('node:fs/promises');
const { createHash } = await import('node:crypto');
const a = input.answer;
const c = input.capture;
const humanResponse = JSON.stringify(a);
if (a.choice === 'stop') return { route: 'stop', feedback: '', humanResponse, summary: 'A person stopped the change at plan approval.' };
if (a.choice === 'revise') return { route: 'revise', humanResponse, summary: 'A person requested plan changes.',
  feedback: 'A person reviewed the plan and asked for changes. Their words: ' + (a.comment ?? '') + (c.feedback ? '\n\nOutstanding review findings:\n' + c.feedback : '') };
let current = null;
try { current = createHash('sha256').update(await fs.readFile(c.file, 'utf8')).digest('hex'); } catch { /* treated as changed */ }
if (current !== c.revision) return { route: 'revise', humanResponse, summary: 'The plan changed after it was shown for approval.',
  feedback: 'The plan file changed or became unreadable after a person approved revision ' + c.revision + '. That approval does not cover the current text. Confirm the plan is as intended and return it for approval again. Do not make further changes unless needed.' };
return { route: 'build', feedback: '', humanResponse, summary: 'A person approved the plan.' + (a.comment ? ' Comment: ' + a.comment : '') };

const r = input.review;
const until = input.grant?.until ?? 3;
const planOwned = r.findings.filter((f) => f.owner === 'plan' && f.severity !== 'minor');
const repair = planOwned.length ? 'replan' : 'fix';
let route;
if (r.verdict === 'pass') route = 'deliver';
else if (r.verdict === 'blocked' || input.count >= until) route = 'ask';
else route = repair;
const list = r.findings.map((f) => '[' + f.id + ' ' + f.severity + ', ' + f.owner + '] ' + f.location + ': ' + f.details).join('\n');
return { route, repair, count: input.count, summary: r.summary,
  feedback: planOwned.length ? 'Independent review of the built change found problems that belong to the plan, not the code. Correct the plan, keeping ids stable:\n' + planOwned.map((f) => '[' + f.id + '] ' + f.location + ': ' + f.details).join('\n') : '',
  question: (r.verdict === 'blocked' ? 'The review could not be completed. ' + r.limitations.join(' ') : 'The change still has findings after ' + input.count + ' reviews.') + ' Allow up to three more review rounds, or stop and keep the work as it is?',
  context: 'Continuing keeps the original requirements and the outstanding findings. It does not accept defects or authorize new scope.',
  evidence: (r.summary + '\n\n' + list).slice(0, 32000), revision: r.reviewedCommit };

const d = input.decision;
const go = input.answer.choice === 'continue';
return { route: go ? d.repair : 'stop', until: d.count + 3, feedback: d.feedback, humanResponse: JSON.stringify(input.answer),
  summary: go ? 'A person allowed further repair.' : 'A person stopped the change during review.' };

const { execFileSync } = await import('node:child_process');
const git = (...args) => execFileSync('git', args, { cwd: input.root.repoPath, encoding: 'utf8' }).trim();
if (input.review.verdict !== 'pass') throw new Error('Delivery requires a passing review');
const head = git('rev-parse', 'HEAD');
if (head !== input.review.reviewedCommit) throw new Error('The checkout is at ' + head + ' but review passed at ' + input.review.reviewedCommit + '. Review the new commit before delivery.');
return { route: input.root.createPr ? 'pr' : 'local', branch: git('rev-parse', '--abbrev-ref', 'HEAD'), reviewedCommit: head };

const { root, review, deliver, pr } = input;
const minor = review.findings.map((f) => 'Minor finding left open: [' + f.id + '] ' + f.location + ': ' + f.details);
const unchecked = review.checksPassed === null ? ['No check commands were run by Interlock for the final review.'] : [];
const blocked = root.createPr && !pr?.prUrl;
return { outcome: blocked ? 'delivery_blocked' : pr?.prUrl ? 'pr_created' : 'local_complete', verification: 'passed',
  taskDir: root.taskDir, branch: deliver.branch, reviewedCommit: deliver.reviewedCommit, prUrl: pr?.prUrl ?? null,
  summary: (pr?.summary ?? review.summary),
  limitations: [...(blocked ? ['A pull request was requested but not opened. ' + (pr?.summary ?? '')] : []), ...unchecked, ...minor,
    ...(pr?.prUrl ? ["The pull request's own CI had not finished when this workflow ended."] : []),
    ...review.limitations.map((l) => 'Review note, written before delivery: ' + l)] };

const { root, previous, review, build } = input;
return { outcome: 'stopped', verification: 'incomplete', taskDir: root.taskDir, branch: build?.branch ?? null,
  reviewedCommit: review?.reviewedCommit ?? null, prUrl: null,
  summary: (previous.summary ?? 'Stopped by a person.') + (build ? ' Work so far is on branch ' + build.branch + ' at ' + build.headCommit + '.' : ' No code was written.'),
  limitations: [previous.humanResponse ? 'Human decision: ' + previous.humanResponse : 'A person chose to stop.',
    ...(review?.findings ?? []).map((f) => 'Open finding: [' + f.id + ' ' + f.severity + '] ' + f.location + ': ' + f.details)] };

const r = { ...input.review };
r.findings = r.findings ?? [];
r.limitations = r.limitations ?? [];
const material = r.findings.some((f) => f.severity === 'blocker' || f.severity === 'major');
if (r.verdict === 'ready' && material) r.verdict = 'revise';
if (r.verdict === 'revise' && !material) r.verdict = 'ready';
if (r.verdict === 'blocked' && r.limitations.length === 0) r.limitations = ['Reviewer returned blocked without naming the missing evidence.'];
return r;

const r = { ...input.review };
r.findings = r.findings ?? [];
r.limitations = r.limitations ?? [];
const material = r.findings.some((f) => f.severity === 'blocker' || f.severity === 'major');
if (r.verdict === 'ready' && material) r.verdict = 'revise';
if (r.verdict === 'revise' && !material) r.verdict = 'ready';
if (r.verdict === 'blocked' && r.limitations.length === 0) r.limitations = ['Reviewer returned blocked without naming the missing evidence.'];
return r;

const { execFileSync, spawnSync } = await import('node:child_process');
const fs = await import('node:fs/promises');
const i = input.run;
const repoPath = await fs.realpath(i.repoPath);
const git = (...args) => execFileSync('git', args, { cwd: repoPath, encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 }).trim();
const commit = (ref) => git('rev-parse', '--verify', ref + '^{commit}');
const headCommit = commit(i.headRef || 'HEAD');
const baseCommit = git('merge-base', commit(i.baseRef), headCommit);
if (baseCommit === headCommit) throw new Error('No change to review: head equals its merge base with ' + i.baseRef);
const changedFiles = git('diff', '--name-only', baseCommit, headCommit).split('\n').filter(Boolean);
const diffStat = git('diff', '--shortstat', baseCommit, headCommit);
const commands = i.checkCommands ?? [];
const atHead = git('rev-parse', 'HEAD') === headCommit;
const dirty = git('status', '--porcelain', '--untracked-files=no') !== '';
let skipReason = null;
if (commands.length === 0) skipReason = 'No check commands were supplied.';
else if (!atHead) skipReason = 'The checkout is not at the commit under review, so checks were not run.';
else if (dirty) skipReason = 'The checkout has uncommitted changes to tracked files, so checks would not test the commit under review.';
const checks = [];
for (const command of commands) {
  if (skipReason) { checks.push({ command, exitCode: null, status: 'not_run', durationMs: 0, outputTail: skipReason }); continue; }
  const started = Date.now();
  const run = () => spawnSync(command, { cwd: repoPath, shell: true, encoding: 'utf8', timeout: 900000, maxBuffer: 64 * 1024 * 1024, env: { ...process.env, CI: '1' } });
  let r = run();
  const first = r.status === 0 || r.error ? null : ((r.stdout ?? '') + (r.stderr ?? '')).trim().slice(-1500);
  if (first !== null) r = run();
  const output = ((r.stdout ?? '') + (r.stderr ?? '')).trim();
  const exitCode = typeof r.status === 'number' ? r.status : null;
  const flaky = first !== null && exitCode === 0;
  checks.push({ command, exitCode, status: exitCode === 0 ? 'passed' : 'failed', durationMs: Date.now() - started, attempts: first === null ? 1 : 2,
    outputTail: (r.error ? String(r.error.message) + '\n' : '') + (flaky ? 'Passed on the second attempt. First attempt failed with:\n' + first : output.slice(-3000)) });
}
const ran = checks.filter((c) => c.status !== 'not_run');
return { repoPath, baseCommit, headCommit, changedFiles: changedFiles.slice(0, 400), changedFileCount: changedFiles.length, diffStat,
  checks, checksPassed: ran.length === 0 ? null : ran.every((c) => c.status === 'passed'), checksNote: skipReason,
  criteria: i.criteria ?? null, criteriaPath: i.criteriaPath ?? null, priorReview: i.priorReview ?? null, focus: i.focus ?? null };

const pre = input.pre;
const r = { ...input.review };
r.findings = [...(r.findings ?? [])];
const add = (id, details) => r.findings.push({ id, owner: 'implementation', severity: 'major', location: 'review rules', details });
if (r.verdict !== 'blocked') {
  if (r.reviewedCommit !== pre.headCommit) add('rule-commit', 'The review names commit ' + r.reviewedCommit + ' but the commit under review is ' + pre.headCommit + '.');
  r.findings = r.findings.map((f) => (f.owner === 'environment' ? { ...f, severity: 'minor' } : f));
  if (pre.checksPassed === false) {
    const excused = r.findings.filter((f) => f.owner === 'environment').map((f) => f.location + ' ' + f.details).join('\n');
    const failed = pre.checks.filter((c) => c.status === 'failed' && !excused.includes(c.command)).map((c) => c.command);
    if (failed.length && !r.findings.some((f) => f.severity !== 'minor')) add('rule-checks', 'Required check commands failed: ' + failed.join('; '));
  }
  const open = (r.criteria ?? []).filter((c) => c.status !== 'verified').map((c) => c.id);
  if (r.verdict === 'pass' && open.length) add('rule-criteria', 'Criteria not verified: ' + open.join(', '));
  if (r.verdict === 'pass' && (r.resolutions ?? []).some((x) => x.status === 'unresolved')) add('rule-resolutions', 'Earlier findings remain unresolved.');
  const material = r.findings.some((f) => f.severity === 'blocker' || f.severity === 'major');
  r.verdict = material ? 'revise' : 'pass';
}
r.reviewedCommit = pre.headCommit;
return { ...r, baseCommit: pre.baseCommit, headCommit: pre.headCommit, checksPassed: pre.checksPassed,
  checks: pre.checks.map((c) => ({ command: c.command, exitCode: c.exitCode, status: c.status })) };

